"""
Provide the creation of collector configuration for gNodeB with all in cloud deployment.
"""
from typing import Any, Dict
from taf.ul.log_collection.config.builders.protocols.gnb import GnbProtocolsCollectorConfigurator


class CloudGnbProtocolsCollectorConfigurator(GnbProtocolsCollectorConfigurator):
    """
    Configuration creation for protocols logs on classical gNodeBs.
    Attributes:
        protocol_capture_details: stores the network interfaces and the components on which protocol messages are sent

    """
    protocol_capture_details: dict = {
        "f1c": {"component": "CPIF", "network_interface": "f1c"},
        "e1c": {"component": "CPNRT", "network_interface": "e1"},
        "ngc": {"component": "CPIF", "network_interface": "ngc"},
        "xnc": {"component": "CPIF", "network_interface": "xnc"},
        "x2c": {"component": "CPIF", "network_interface": "x2c"},
    }

    def add_protocols(self: Any, ne_log_name: str, ne_log_configuration: dict) -> None:
        """
        Create collector configurations for all interfaces in provided 'configuration',
        add them as members to collector group with name given in configuration
        and append them to the global collector configuration list of the builder.

        :param ne_log_name: The name of the collector given in configuration
        :param ne_log_configuration: tcpdump specific configuration dictionary,
            requires 'type' and 'interfaces' information,
            e.g:
                ne_log_configuration = {'type': 'protocols', 'interfaces': 'e1c, f1c'}


        Create for several components the collector configurations and appends them to
        the global collector configuration list of the builder
        """

        self._verify_configuration(ne_log_configuration)
        interfaces = self._get_interfaces_from_configuration(ne_log_configuration)
        collector_configuration: Dict[str, Any] = {
            'name': ne_log_name,
            'type': "group",
            'members': []
        }
        for interface in interfaces:
            collector_name = f"{interface}_{self.ne_type}_{self.ne_id}"
            self._add_protocol(interface=interface, collector_name=collector_name)
            collector_configuration['members'].append(collector_name)
        self._collector_configuration_data.append(collector_configuration)

    def _add_protocol(self, interface: str, collector_name: str) -> None:
        """
        Create a protocol collector configuration on vCU and appends it to the global collector configuration
        """
        component, network_interface = self._get_protocol_capture_details(interface)
        collector_configuration = self._create_protocol_collector_configuration(
            collector_name=collector_name,
            component=component,
            network_interface=network_interface)
        self._collector_configuration_data.append(collector_configuration)

    def _get_protocol_capture_details(self, interface: str) -> tuple:
        """
        Get the component and interface for the given protocol interface

        :param interface: protocol interface name
        :returns: component and network interface
        """
        return (
            self.protocol_capture_details[interface]['component'],
            self.protocol_capture_details[interface]['network_interface']
        )

    def _create_protocol_collector_configuration(self: Any, collector_name: str, component: str, network_interface: str) -> dict:
        namespace = self.tl_config_information_provider.get_cu_namespace(self.ne_id)
        pod_name = self.k8s_information_provider.get_pod(self.ne_id, du_id=None, component=component)
        container_name = self.k8s_information_provider.get_container(self.ne_id, component=component, container_part='nwmgmt')
        return self._create_vcu_collector_configuration(
            vcu_collector_name=collector_name,
            namespace=namespace,
            pod=pod_name,
            container=container_name,
            interface=network_interface,
            proto_filter="sctp")

    def _create_vcu_collector_configuration(
            self: Any,
            vcu_collector_name: str,
            namespace: str,
            pod: str,
            container: str,
            interface: str,
            proto_filter: str = "") -> dict:
        cu_ssh_details = self.tl_config_information_provider.get_cu_master_node_ssh_details(node_id=self.ne_id)
        collector_configuration = {
            'name': vcu_collector_name,
            'type': 'tcpdump',
            'options': f"{proto_filter} -i {interface} -U",
            'kubectl_exec_options': f"-n {namespace} {pod} -c {container}",
            'executor': {
                'host': cu_ssh_details.addr,
                'user': cu_ssh_details.username,
                'password': cu_ssh_details.password
            },
            'capture_locally': 'yes'
        }
        return collector_configuration
